def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if tz is not None:
            return Time(nanoseconds, tz)
        else:
            return Time(nanoseconds)
    except ValueError as e:
        raise ValueError("Invalid input for hydrate_time: " + str(e))
    except TypeError as e:
        raise TypeError("Invalid input type for hydrate_time: " + str(e))

