def shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not seq:
        return []
    else:
        return list(seq)

    # Fisher-Yates shuffle
    for i in range(len(seq) - 1, 0, -1):
        j = random.randint(0, i)
        seq[i], seq[j] = seq[j], seq[i]
    return seq

