def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("sequence must be a list or tuple")

    if output is not None and not isinstance(output, (list, tuple)):
        raise TypeError("output must be a list or tuple")

    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(item)
        elif isinstance(item, Interface):
            output.append(item)
        else:
            raise TypeError("invalid item in sequence")

    return tuple(output)

