def find_tags(text, replacer=None):
    tags = set()
    original_text = text

    # Find tags inside code blocks
    in_code_block = False
    for i, char in enumerate(text):
        if char == '`':
            in_code_block = not in_code_block
        if in_code_block:
            continue

        # Find tags
        if char == '#':
            start_index = i
            while i < len(text) and text[i].isalnum():
                i += 1
            tag = text[start_index:i]
            tags.add(tag)

    # Replace tags with replacer function
    if replacer is not None:
        for tag in tags:
            text = text.replace(tag, replacer(tag))

    return tags, text

