def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of argument names and their default values.
    """
    # Initialize an empty dictionary to store the resolved defaults
    resolved_defaults = {}

    # Iterate over the arguments in the spec
    for arg_name, arg_spec in self.spec.items():
        # Check if the argument has a default value
        if 'default' in arg_spec:
            # If the argument has a default value, add it to the resolved defaults dictionary
            resolved_defaults[arg_name] = arg_spec['default']
        else:
            # If the argument does not have a default value, check if it has a default value in other sources
            if 'default_source' in arg_spec:
                # If the argument has a default value in other sources, add it to the resolved defaults dictionary
                resolved_defaults[arg_name] = self.get_default_from_source(arg_spec['default_source'])
            else:
                # If the argument does not have a default value in other sources, raise an exception
                raise ValueError(f"Argument '{arg_name}' does not have a default value and no default source was specified.")

    # Return the resolved defaults dictionary
    return resolved_defaults

